import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor dwconv2d_depthwise_k1_forward(torch::Tensor x,
                                            torch::Tensor w,
                                            c10::optional<torch::Tensor> b,
                                            int stride, int padding, int dilation);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void dwconv2d_k1_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int C, int H, int Win,
    int K, int stride, int padding, int dilation,
    int Hout, int Wout,
    int RowsNeeded)
{
  // CTA-level tiling: each block covers CcPerBlock channels x TileOW output columns,
  // and iterates over Hout in chunks of TileH, staging the needed (overlapping) input
  // rows for the K-tap sliding window along H into double-buffered shared memory,
  // allowing the next H-tile's input rows to be prefetched from global memory while
  // the current tile's already-staged data is being consumed for compute, overlapping
  // global memory latency with useful work across H-tile iterations.
  constexpr int CcPerBlock = 4;
  constexpr int TileOW     = 32;
  constexpr int TileH      = 32;
  const int tid = threadIdx.x;
  const int cc  = tid / TileOW;
  const int ow_local = tid % TileOW;
  const int n = blockIdx.z;
  const int c_base = blockIdx.y * CcPerBlock;
  const int ow_base = blockIdx.x * TileOW;
  const int c  = c_base + cc;
  const int ow = ow_base + ow_local;
  const int64_t sXn = (int64_t)C * H * Win;
  const int64_t sXc = (int64_t)H * Win;
  const int64_t sYn = (int64_t)C * Hout * Wout;
  const int64_t sYc = (int64_t)Hout * Wout;
  extern __shared__ unsigned char smem_raw[];
  T* sW = reinterpret_cast<T*>(smem_raw);        // [CcPerBlock * K]
  T* sX = sW + CcPerBlock * K;                   // [2 * CcPerBlock * TileOW * RowsNeeded] (double buffered)
  // Cooperative load of the (small) per-channel weight vector into shared memory.
  for (int idx = tid; idx < CcPerBlock * K; idx += blockDim.x) {
    int cc_i = idx / K;
    int k_i  = idx - cc_i * K;
    int c_i  = c_base + cc_i;
    T wval = T(0);
    if (c_i < C) {
      wval = W[(int64_t)c_i * K + k_i];
    }
    sW[idx] = wval;
  }
  __syncthreads();
  const bool row_active = (c < C) && (ow < Wout);
  const int  iw = ow * stride - padding;               // kw == 1 => iw independent of oh
  const bool w_valid = row_active && (iw >= 0 && iw < Win);
  float bval = 0.0f;
  if (B != nullptr && c < C) {
    bval = (float)B[c];
  }
  const int sx_row_stride = RowsNeeded;
  const int sx_col_base   = (cc * TileOW + ow_local) * sx_row_stride;
  const int bufElems = CcPerBlock * TileOW * RowsNeeded;
  const int numTiles = (Hout + TileH - 1) / TileH;
  // Prologue: stage the first H-tile's rows into buffer 0.
  {
    const int ih_start0 = 0 * stride - padding;
    for (int r = 0; r < RowsNeeded; ++r) {
      int ih = ih_start0 + r;
      T xval = T(0);
      if (w_valid && ih >= 0 && ih < H) {
        xval = X[(int64_t)n * sXn + (int64_t)c * sXc + (int64_t)ih * Win + iw];
      }
      sX[sx_col_base + r] = xval;
    }
  }
  __syncthreads();
  for (int i = 0; i < numTiles; ++i) {
    const int oh_base = i * TileH;
    const int cur = i & 1;
    const int nxt = cur ^ 1;
    // Prefetch the next H-tile's rows into the other buffer while the current
    // tile's already-staged data is consumed below (software pipelining).
    if (i + 1 < numTiles) {
      const int oh_base_next = (i + 1) * TileH;
      const int ih_start_next = oh_base_next * stride - padding;
      for (int r = 0; r < RowsNeeded; ++r) {
        int ih = ih_start_next + r;
        T xval = T(0);
        if (w_valid && ih >= 0 && ih < H) {
          xval = X[(int64_t)n * sXn + (int64_t)c * sXc + (int64_t)ih * Win + iw];
        }
        sX[nxt * bufElems + sx_col_base + r] = xval;
      }
    }
    const int oh_count = min(TileH, Hout - oh_base);
    if (row_active && w_valid) {
      float acc[TileH];
      #pragma unroll
      for (int t = 0; t < TileH; ++t) acc[t] = bval;
      for (int k = 0; k < K; ++k) {
        float wval = (float)sW[cc * K + k];
        int koff = k * dilation;
        #pragma unroll
        for (int t = 0; t < TileH; ++t) {
          if (t < oh_count) {
            int r = t * stride + koff;
            float xval = (float)sX[cur * bufElems + sx_col_base + r];
            acc[t] += xval * wval;
          }
        }
      }
      #pragma unroll
      for (int t = 0; t < TileH; ++t) {
        if (t < oh_count) {
          int oh = oh_base + t;
          Y[(int64_t)n * sYn + (int64_t)c * sYc + (int64_t)oh * Wout + ow] = static_cast<T>(acc[t]);
        }
      }
    }
    __syncthreads();
  }
}
torch::Tensor dwconv2d_depthwise_k1_forward(torch::Tensor x,
                                            torch::Tensor w,
                                            c10::optional<torch::Tensor> b,
                                            int stride, int padding, int dilation) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");
  TORCH_CHECK(x.dim() == 4, "x must be [N, C, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [C, 1, K, 1] for depthwise conv (groups=C)");
  int64_t N   = x.size(0);
  int64_t C   = x.size(1);
  int64_t H   = x.size(2);
  int64_t Win = x.size(3);
  TORCH_CHECK(w.size(0) == C, "w.size(0) must equal C");
  TORCH_CHECK(w.size(1) == 1, "w.size(1) must be 1 for depthwise");
  TORCH_CHECK(w.size(3) == 1, "w.size(3) must be 1 for (kernel_width=1)");
  int64_t K = w.size(2);
  TORCH_CHECK(stride > 0 && dilation > 0, "stride and dilation must be > 0");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");
  int64_t Hout = (H + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
  int64_t Wout = (Win + 2 * padding - dilation * (1 - 1) - 1) / stride + 1; // kw=1
  TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size computed");
  auto x_c = x.contiguous();
  auto w_c = w.contiguous();
  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == C, "bias must be [C]");
    b_ptr = b_c.data_ptr<float>();
  }
  auto y = torch::empty({N, C, Hout, Wout}, x.options());
  constexpr int CcPerBlock = 4;
  constexpr int TileOW     = 32;
  constexpr int TileH      = 32;
  dim3 block(CcPerBlock * TileOW);
  dim3 grid(
      (unsigned)((Wout + TileOW - 1) / TileOW),
      (unsigned)((C + CcPerBlock - 1) / CcPerBlock),
      (unsigned)N
  );
  int RowsNeeded = (int)((int64_t)(TileH - 1) * stride + (int64_t)(K - 1) * dilation + 1);
  size_t shared_bytes = (size_t)(CcPerBlock * K + 2 * CcPerBlock * TileOW * RowsNeeded) * sizeof(float);
  if (shared_bytes > 48 * 1024) {
    cudaFuncSetAttribute(
        dwconv2d_k1_kernel<float>,
        cudaFuncAttributeMaxDynamicSharedMemorySize,
        (int)shared_bytes);
  }
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  dwconv2d_k1_kernel<float><<<grid, block, shared_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)C, (int)H, (int)Win,
      (int)K, (int)stride, (int)padding, (int)dilation,
      (int)Hout, (int)Wout,
      RowsNeeded
  );
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "dwconv2d_k1_kernel launch failed: ", cudaGetErrorString(err));
  return y;
}
"""

dwconv2d_ext = load_inline(
    name="cute_dwconv2d_k1_ext_model",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["dwconv2d_depthwise_k1_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include", "/root/cutegen_test/cutegen/cutlass/include/cute/"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Depthwise 2D convolution with vertical asymmetric kernel (kernel_size x 1),
    implemented with a single custom CUDA kernel using CuTe.
    """
    def __init__(self,
                 in_channels: int,
                 kernel_size: int,
                 stride: int = 1,
                 padding: int = 0,
                 dilation: int = 1,
                 bias: bool = False) -> None:
        super().__init__()
        assert isinstance(kernel_size, int) and kernel_size >= 1
        assert isinstance(stride, int) and stride >= 1
        assert isinstance(padding, int) and padding >= 0
        assert isinstance(dilation, int) and dilation >= 1

        self.in_channels = int(in_channels)
        self.kernel_size = int(kernel_size)
        self.stride = int(stride)
        self.padding = int(padding)
        self.dilation = int(dilation)

        # Depthwise: groups = in_channels, out_channels = in_channels
        C = self.in_channels
        K = self.kernel_size
        # Weight shape matches PyTorch depthwise layout: [C_out, C_in/groups, Kh, Kw] with groups=C => [C,1,K,1]
        self.weight = nn.Parameter(torch.empty(C, 1, K, 1))
        if bias:
            self.bias = nn.Parameter(torch.empty(C))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = dwconv2d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.kernel_size  # depthwise per-channel fan_in equals kernel_size along H (Kw=1)
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.dwconv2d_depthwise_k1_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            int(self.stride),
            int(self.padding),
            int(self.dilation),
        )

